import{_ as n,o as h,c as g,a3 as i}from"./chunks/framework.DX_KL3e0.js";const o="/help/screenshots/dat-phong/tong-quan.png",a="/help/screenshots/dat-phong/lich-su.png",m=JSON.parse('{"title":"Đặt Phòng Họp","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/dat-phong.md","filePath":"chuc-nang/dat-phong.md","lastUpdated":1782639524000}'),c={name:"chuc-nang/dat-phong.md"};function r(l,t,e,s,u,d){return h(),g("div",null,[...t[0]||(t[0]=[i('<h1 id="đat-phong-hop" tabindex="-1">Đặt Phòng Họp <a class="header-anchor" href="#đat-phong-hop" aria-label="Permalink to &quot;Đặt Phòng Họp&quot;">​</a></h1><p>Module <strong>Đặt Phòng Họp</strong> giúp nhân viên đặt phòng họp trực tuyến, tránh trùng lịch và theo dõi lịch sử sử dụng phòng. Giao diện hiển thị theo vai trò: người dùng đặt phòng cá nhân, quản trị viên có thêm duyệt/quản lý phòng.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/room-bookings</code> (menu <strong>Đặt Phòng Họp</strong> ở nhóm <em>Hoạt Động</em>).</li><li><strong>Lịch sử:</strong> <code>/room-bookings/usage-history</code>.</li><li><strong>Ai dùng được:</strong> Mọi người dùng (đặt phòng); quản trị viên có thêm chức năng duyệt và quản lý phòng.</li><li><strong>Trạng thái lượt đặt:</strong> Chờ duyệt · Đã duyệt · Từ chối.</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+o+'" alt="Trang Đặt phòng họp"></p><p>Màn hình hiển thị lịch các lượt đặt phòng. Mỗi lượt đặt thể hiện phòng, khung giờ và trạng thái (Chờ duyệt / Đã duyệt / Từ chối). Có chú thích màu để phân biệt trạng thái.</p><h2 id="thao-tac-chinh" tabindex="-1">Thao tác chính <a class="header-anchor" href="#thao-tac-chinh" aria-label="Permalink to &quot;Thao tác chính&quot;">​</a></h2><h3 id="đat-phong-hop-1" tabindex="-1">Đặt phòng họp <a class="header-anchor" href="#đat-phong-hop-1" aria-label="Permalink to &quot;Đặt phòng họp&quot;">​</a></h3><ol><li>Nhấn nút <strong>đặt phòng</strong>.</li><li>Trong cửa sổ đặt phòng, điền: <ul><li><strong>Phòng Họp</strong> — chọn phòng.</li><li><strong>Ngày Đặt Phòng</strong>.</li><li><strong>Giờ Bắt Đầu</strong> và <strong>Giờ Kết Thúc</strong>.</li><li><strong>Nội Dung Cuộc Họp</strong> — mô tả mục đích.</li><li><strong>Số Lượng Người Tham Dự</strong> và (tùy chọn) chọn người tham dự.</li></ul></li><li>Hệ thống tự <strong>kiểm tra trùng giờ</strong> với các lượt đặt khác của cùng phòng.</li><li>Nhấn lưu để gửi yêu cầu đặt phòng.</li></ol><div class="warning custom-block"><p class="custom-block-title">Tránh trùng giờ</p><p>Nếu khung giờ bạn chọn <strong>chồng lấn</strong> với một lượt đặt đã có ở cùng phòng, hệ thống sẽ cảnh báo. Hãy đổi giờ hoặc chọn phòng khác trước khi lưu.</p></div><div class="info custom-block"><p class="custom-block-title">Quy tắc trùng giờ</p><p>Hai lượt đặt được coi là trùng khi: <em>giờ bắt đầu của lượt này &lt; giờ kết thúc của lượt kia</em> <strong>và</strong> <em>giờ kết thúc của lượt này &gt; giờ bắt đầu của lượt kia</em>.</p></div><h3 id="duyet-yeu-cau-quan-tri-vien" tabindex="-1">Duyệt yêu cầu (quản trị viên) <a class="header-anchor" href="#duyet-yeu-cau-quan-tri-vien" aria-label="Permalink to &quot;Duyệt yêu cầu (quản trị viên)&quot;">​</a></h3><ol><li>Quản trị viên xem các lượt <strong>Chờ duyệt</strong>.</li><li>Bấm vào một lượt đặt (ở cả ba kiểu xem <strong>Lịch · Bảng · Lưới</strong>) để mở cửa sổ chi tiết: xem thông tin, kiểm tra xung đột phòng, <strong>Duyệt Ngay</strong> hoặc <strong>Từ Chối</strong> (có thể nhập lý do), hoặc <strong>Sửa</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Duyệt nhanh ngay trên Telegram</p><p>Khi có người đặt phòng mới, người nhận thông báo (cấu hình ở mục <strong>Cấu Hình Phòng Họp</strong>) nhận tin nhắn Telegram kèm hai nút <strong>✅ Duyệt</strong> / <strong>❌ Từ chối</strong> và nút <strong>Xem chi tiết</strong>. Bấm thẳng trên Telegram là lượt đặt được xử lý ngay, không cần mở web. Nếu từ chối qua Telegram mà không nhập lý do, hệ thống ghi mặc định <em>&quot;Phòng họp không khả dụng&quot;</em>.</p></div><div class="warning custom-block"><p class="custom-block-title">Sửa lượt đã duyệt = duyệt lại</p><p>Khi người đặt <strong>chỉnh sửa</strong> một lượt đã được duyệt (đổi phòng/giờ/người tham dự), lượt đó tự chuyển về <strong>Chờ duyệt</strong> và gửi lại yêu cầu cho người duyệt.</p></div><h3 id="huy-luot-đat" tabindex="-1">Hủy lượt đặt <a class="header-anchor" href="#huy-luot-đat" aria-label="Permalink to &quot;Hủy lượt đặt&quot;">​</a></h3><ol><li>Mở chi tiết lượt đặt.</li><li>Chọn <strong>Hủy</strong> và nhập lý do hủy (nếu được yêu cầu).</li><li>Xác nhận — lượt đặt được gỡ khỏi lịch.</li></ol><h3 id="xem-lich-su-su-dung-phong" tabindex="-1">Xem lịch sử sử dụng phòng <a class="header-anchor" href="#xem-lich-su-su-dung-phong" aria-label="Permalink to &quot;Xem lịch sử sử dụng phòng&quot;">​</a></h3><ol><li>Truy cập <code>/room-bookings/usage-history</code> (<strong>Lịch Sử Sử Dụng Phòng</strong>).</li><li>Xem thống kê và lịch sử các lượt sử dụng phòng theo thời gian.</li></ol><p><img src="'+a+'" alt="Lịch sử sử dụng phòng họp"></p><p>Xem thêm trang phân tích: <a href="/help/chuc-nang/hieu-suat-phong-hop.html">Hiệu Suất Phòng Họp</a></p><h2 id="cau-hinh-phong-hop-chi-quan-tri-toi-cao" tabindex="-1">Cấu Hình Phòng Họp (chỉ Quản trị tối cao) <a class="header-anchor" href="#cau-hinh-phong-hop-chi-quan-tri-toi-cao" aria-label="Permalink to &quot;Cấu Hình Phòng Họp (chỉ Quản trị tối cao)&quot;">​</a></h2><p>Ở cuối trang Đặt Phòng Họp, <strong>Quản trị tối cao</strong> thấy nút <strong>⚙️ Cấu Hình Phòng Họp</strong>. Mở ra gồm 2 tab:</p><ul><li><strong>Người Nhận Thông Báo</strong> — chọn các tài khoản sẽ nhận thông báo (in-app + Telegram kèm nút Duyệt/Từ chối) mỗi khi có lượt đặt phòng mới chờ duyệt. Để trống sẽ dùng tài khoản quản trị tối cao mặc định.</li><li><strong>Quản Lý Phòng</strong> — thêm/sửa/ẩn danh sách phòng họp.</li></ul><div class="info custom-block"><p class="custom-block-title">Điều kiện nhận thông báo</p><p>Một người chỉ thực sự nhận được thông báo khi tài khoản của họ <strong>bật &quot;Bật Thông Báo&quot;</strong> trong phần Phân Quyền người dùng. Nếu tắt, dù có trong danh sách Người Nhận Thông Báo cũng sẽ không nhận.</p></div><h2 id="ai-nhan-thong-bao-khi-nao" tabindex="-1">Ai nhận thông báo khi nào? <a class="header-anchor" href="#ai-nhan-thong-bao-khi-nao" aria-label="Permalink to &quot;Ai nhận thông báo khi nào?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sự kiện</th><th style="text-align:center;">Người đặt</th><th style="text-align:center;">Người tham dự</th><th style="text-align:center;">Người nhận (cấu hình)</th></tr></thead><tbody><tr><td>Tạo lượt đặt mới</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅ (kèm nút Duyệt/Từ chối)</td></tr><tr><td>Được <strong>duyệt</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td></tr><tr><td>Bị <strong>từ chối</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td></tr><tr><td>Người đặt <strong>sửa</strong> (duyệt lại)</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><strong>Hủy</strong> / <strong>Xác nhận đã dùng</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr></tbody></table><p>Mọi thông báo đều gửi <strong>đồng thời in-app và Telegram</strong> (nếu tài khoản đã liên kết Telegram và bật thông báo).</p><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Vì sao tôi không đặt được phòng vào khung giờ mong muốn?</strong> Khung giờ đó đã có lượt đặt khác cho cùng phòng. Hãy chọn khung giờ trống hoặc một phòng khác.</p><p><strong>Đặt phòng xong có cần chờ duyệt không?</strong> Tùy cấu hình: một số lượt đặt ở trạng thái <em>Chờ duyệt</em> cho đến khi quản trị viên duyệt. Bạn theo dõi trạng thái ngay trên lịch.</p><p><strong>Tôi đặt nhầm thì xử lý thế nào?</strong> Mở lượt đặt và chọn <strong>Hủy</strong>. Nếu lượt đã được duyệt, có thể cần quản trị viên hỗ trợ hủy/sửa.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/cong-viec.html">Công Việc</a> · <a href="/help/chuc-nang/dashboard.html">Dashboard</a></p>',34)])])}const y=n(c,[["render",r]]);export{m as __pageData,y as default};
